from pathlib import Path
p=Path('work/pocket-research/interaction-tests.cjs');s=p.read_text(encoding='utf-8');i=s.index('fs.writeFileSync');s=s[:i]+'''
function field(s,p,name,key=950){s.players[p.id].hand.push({id:named(name).id,key});return R.apply(s,{type:'trainer',player:p.id,card:key});}
test('Stadiums replace into their original owner discard and limit plays per turn',()=>{let{s,p,o}=fixture();s=field(s,p,'Training Area');assert.equal(s.stadium.ref.key,950);const before=JSON.stringify(s);assert.throws(()=>field(structuredClone(s),s.players[p.id],'Starting Plains',951),/already played/);assert.equal(JSON.stringify(s),before);s.active=o.id;s=field(s,s.players[o.id],'Starting Plains',952);assert(s.players[p.id].discard.some(x=>x.key===950));assert.equal(s.stadium.player,o.id);});
test('Identical Stadium cannot replace itself, even from a different printing',()=>{let{s,p,o}=fixture();s=field(s,p,'Training Area');s.active=o.id;assert.throws(()=>field(s,s.players[o.id],'Training Area',951),/already in play/);});
test('Starting Plains raises both players Basic HP and drops the bonus on evolution',()=>{let{s,p,o}=fixture();s=field(s,p,'Starting Plains');assert.equal(R.maximumHp(s.players[p.id].active,s),get('a1-001').hp+20);assert.equal(R.maximumHp(s.players[o.id].active,s),get('a1-128').hp+20);s.players[p.id].active.stack.push(ref('a1-002',980));assert.equal(R.maximumHp(s.players[p.id].active,s),get('a1-002').hp);});
test('Replacing an HP Stadium immediately checks for a knockout',()=>{let{s,p,o}=fixture();s=field(s,p,'Starting Plains');s.players[p.id].active.damage=get('a1-001').hp+10;s.active=o.id;s=field(s,s.players[o.id],'Training Area',951);assert.equal(s.players[p.id].active,null);assert.equal(s.players[o.id].points,1);assert.equal(s.prompt.kind,'promote');});
test('Psychic Stadium retreat discount is shared with the payment query',()=>{let{s,p}=fixture('a1-129');s=field(s,p,'Peculiar Plaza');assert.equal(R.retreatCost(s,s.players[p.id]),Math.max(0,get('a1-129').retreat-2));});
test('Stadium activation is once per player per turn with atomic rejected reuse',()=>{let{s,p}=fixture();s=field(s,p,'Fragrant Forest');s.players[p.id].deck=[ref('a1-001',981)];s=R.apply(s,{type:'stadium',player:p.id});assert(s.players[p.id].hand.some(x=>x.key===981));assert.throws(()=>R.apply(s,{type:'stadium',player:p.id}),/already used/);});
test('Area Zero chooses a Basic in hand before shuffling and drawing',()=>{let{s,p}=fixture();s=field(s,p,'Area Zero');s.players[p.id].hand=[ref('a1-001',981),ref('pa-001',982)];s=R.apply(s,{type:'stadium',player:p.id});assert.deepEqual(s.prompt.options,[981]);s=R.apply(s,{type:'choice',player:p.id,value:981});assert.equal(s.players[p.id].hand.length,2);assert(s.players[p.id].hand.some(x=>x.key===982));});
test('Rainbow Cave replaces generated Energy without triggering attachment Abilities',()=>{let{s,p,o}=fixture('a2-110');s=field(s,p,'Rainbow Cave');s.players[p.id].zone={current:'G',next:'D'};s=R.apply(s,{type:'stadium',player:p.id});assert.equal(s.players[p.id].zone.current,'D');assert(s.players[p.id].energyDiscard.includes('G'));assert.equal(s.players[o.id].active.damage,0);});
test('Hiking Trail draws the ending player up to three cards',()=>{let{s,p}=fixture();s=field(s,p,'Hiking Trail');s.players[p.id].hand=[];s=R.apply(s,{type:'pass',player:p.id});assert.equal(s.players[p.id].hand.length,3);});
test('Soothing Shore heals only the ending players Pokemon with Water Energy',()=>{let{s,p,o}=fixture();s=field(s,p,'Soothing Shore');s.players[p.id].active.energy=['W'];s.players[p.id].active.damage=30;s.players[p.id].bench[0].energy=['G'];s.players[p.id].bench[0].damage=30;s.players[o.id].active.damage=30;s=R.apply(s,{type:'pass',player:p.id});assert.equal(s.players[p.id].active.damage,10);assert.equal(s.players[p.id].bench[0].damage,30);assert.equal(s.players[o.id].active.damage,30);});
''' +s[i:];p.write_text(s,encoding='utf-8')
p=Path('work/pocket-candidate/ui/pocket-ui.js');s=p.read_text(encoding='utf-8');s=s.replace("${[1,0].map(i=>playerView(m,m.players[i])).join('')}</div>","${[1,0].map(i=>playerView(m,m.players[i])).join('')}${m.stadium?`<div class=\"pocket-stadium\"><button onclick=\"PocketUI.inspect('${m.stadium.ref.id}')\">${image(data.byId.get(m.stadium.ref.id))}</button>${data.byId.get(m.stadium.ref.id).program?.[0]?.stadium?.program?`<button onclick=\"PocketUI.act({type:'stadium',player:${m.active}})\">Use Stadium</button>`:''}</div>`:''}</div>")
